int main(void){double value=123;assert(NMStaticValueToDouble(UINT64_MAX,NMStaticValueI64,&value)&&value==-1);assert(NMStaticValueToDouble(UINT32_MAX,NMStaticValueI32,&value)&&value==-1);assert(!NMStaticValueToDouble(UINT64_C(0x7ff0000000000000),NMStaticValueF64,&value)&&value==-1);assert(!NMStaticValueToDouble(0,NMStaticValueAuto,&value));uint32_t words[]={0xd2824680u,0xf2b579a0u,0xd65f03c0u};NMStaticImmediate r={0};assert(NMStaticDecodeImmediate(words,sizeof words,NMStaticValueAuto,&r)&&r.type==NMStaticValueI64&&r.reg==0&&r.bits==0xabcd1234&&r.consumedInstructions==2);assert(!NMStaticDecodeImmediate(words,sizeof words,NMStaticValueI32,&r));uint32_t full[]={0xd29fffe0u,0xf2bfffe0u,0xf2dfffe0u,0xf2ffffe0u,0xd65f03c0u};assert(NMStaticDecodeImmediate(full,sizeof full,NMStaticValueU64,&r)&&r.bits==UINT64_MAX&&r.consumedInstructions==4);uint32_t bad=0x52c00000u;assert(!NMStaticDecodeImmediate(&bad,4,NMStaticValueAuto,&r));bad=0x5280001fu;assert(!NMStaticDecodeImmediate(&bad,4,0,&r));for(unsigned i=0;i<256;i++){uint32_t s=0x1e201000u|(i<<13),d=s|0x00400000u;assert(NMStaticDecodeImmediate(&s,4,NMStaticValueF32,&r)&&r.type==NMStaticValueF32);float f;uint32_t bits=(uint32_t)r.bits;memcpy(&f,&bits,4);assert(f!=0);assert(NMStaticDecodeImmediate(&d,4,NMStaticValueF64,&r)&&r.type==NMStaticValueF64);double v;memcpy(&v,&r.bits,8);assert((double)f==v);assert(!NMStaticDecodeImmediate(&s,4,NMStaticValueF64,&r));}puts("PASS: exact MOVZ/MOVK composition and all 512 scalar FP immediates, width/type/register/length refusals");return 0;}
